// VARIABLES GLOBALES DE CONTROL Y PERSISTENCIA (XP)
let xp = parseInt(localStorage.getItem('xp_div_dec')) || 0;
let activeTab = 's-aprende';
let fcsFlipped = new Set();
let currentFCIdx = 0;

// DATOS ESTRUCTURADOS DEL TEMA
const flashcards = [
  { w: '¿Qué se debe hacer si el divisor tiene decimales?', a: 'Multiplicar dividendo y divisor por 10, 100 o la potencia necesaria para convertir el divisor en entero.' },
  { w: '¿Qué efecto produce un divisor menor que 1?', a: 'Produce un efecto amplificador, haciendo que el cociente sea mayor que el dividendo original.' },
  { w: '¿Cuándo se aplica la regla de "Cero al Cociente"?', a: 'Cuando al bajar la cifra siguiente del dividendo, el número resultante sigue siendo menor que el divisor.' },
  { w: '¿Cómo se manejan los ceros para continuar una división inexacta?', a: 'Se añade un cero al residuo y se coloca el punto decimal en el cociente para proceder con las décimas.' },
  { w: '¿Qué ocurre con el cociente si multiplicamos dividendo y divisor por 10?', a: 'El cociente permanece exactamente igual debido a la propiedad fundamental de la división.' }
];

const quizQuestions = [
  { q: 'Si calculamos 6 ÷ 0.2, ¿cuál es el cociente resultante?', o: ['3', '1.2', '30', '0.3'], a: 2, h: 'Multiplica ambos componentes por 10 para operar 60 ÷ 2.' },
  { q: '¿Qué relación es correcta para la operación 8 ÷ 0.5?', o: ['Cociente < 8', 'Cociente > 8', 'Cociente = 8', 'Cociente = 4'], a: 1, h: 'Cualquier divisor menor que 1 genera un resultado mayor al dividendo.' },
  { q: 'En la operación 4.12 ÷ 4, ¿qué caso especial ocurre en las décimas?', o: ['División exacta inmediata', 'Cero al cociente', 'Se descarta el residuo', 'Amplificación por 100'], a: 1, h: 'Al bajar el 1, este no alcanza al divisor 4, por lo que se anota 0 en el cociente.' },
  { q: 'Para transformar 5.4 ÷ 0.06 en una división de enteros, multiplicamos por:', o: ['10', '100', '1000', 'No se puede'], a: 1, h: 'El divisor tiene dos cifras decimales, requiere un factor de 100.' },
  { q: 'Si una división arroja un residuo de 0 tras procesar los decimales, se clasifica como:', o: ['Inexacta', 'Periódica', 'Exacta', 'Nula'], a: 2, h: 'El residuo cero marca la finalización limpia del reparto.' }
];

const classItems = [
  { t: '12 ÷ 0.2', c: 'left' }, { t: '7 ÷ 0.05', c: 'left' }, { t: '0.8 ÷ 0.1', c: 'left' },
  { t: '15 ÷ 3.5', c: 'right' }, { t: '9.6 ÷ 2', c: 'right' }, { t: '4 ÷ 1.2', c: 'right' }
];

const identStatements = [
  { text: 'Para dividir decimales el divisor debe ser siempre un número decimal.', target: 'decimal.', info: '¡Falso! El divisor debe convertirse siempre a entero antes de operar.' },
  { text: 'Al dividir 5 entre 0.1 el resultado obtenido es menor que cinco.', target: 'menor', info: '¡Falso! Dividir por 0.1 incrementa el valor (da 50).' },
  { text: 'Si una cifra bajada no cabe en el divisor se ignora la posición.', target: 'ignora', info: '¡Falso! Se debe colocar obligatoriamente un cero al cociente.' }
];

const completePhrases = [
  { s: 'Cuando el divisor es menor que 1, el cociente es _______ que el dividendo.', o: ['mayor', 'menor', 'igual'], a: 'mayor' },
  { s: 'Si la cifra del dividendo no alcanza al divisor, se coloca un _______ en el cociente.', o: ['punto', 'cero', 'residuo'], a: 'cero' },
  { s: 'Para eliminar los decimales del divisor se aplica el método de _______.', o: ['amplificación', 'simplificación', 'resta'], a: 'amplificación' }
];

// MATRIZ DE LA SOPA DE LETRAS
const sopaPalabras = ['DIVISOR', 'COCIENTE', 'AMPLIFICAR', 'CERO', 'DECIMAL'];
const sopaGridData = [
  ['A','M','P','L','I','F','I','C','A','R'],
  ['X','D','E','C','I','M','A','L','Q','W'],
  ['C','O','C','I','E','N','T','E','E','R'],
  ['T','Y','U','I','O','P','A','S','D','F'],
  ['G','H','J','K','L','Z','X','C','V','B'],
  ['N','M','D','I','V','I','S','O','R','Q'],
  ['W','E','R','T','Y','U','I','O','P','A'],
  ['S','D','F','G','H','J','K','L','Z','X'],
  ['C','E','R','O','V','B','N','M','Q','W'],
  ['A','S','D','F','G','H','J','K','L','M']
];

// INICIALIZADOR GENERAL
document.addEventListener('DOMContentLoaded', () => {
  updateXPUI();
  loadFC();
  loadQuiz();
  loadClassifica();
  loadIdentifica();
  loadCompleta();
  loadWidgetBuilder();
  loadWidgetComp();
  loadSopa();
  genTask();
  genEval();
});

function updateXPUI() {
  document.getElementById('xpPts').innerText = `⭐ ${xp}`;
  let level = "Novato ✏️";
  if (xp > 40) level = "Calculador 🧮";
  if (xp > 90) level = "Maestro Decimal 🏆";
  document.getElementById('xpLvl').innerText = level;
  
  let fillPct = Math.min(100, (xp / 130) * 100);
  document.getElementById('xpFill').style.width = `${fillPct}%`;
}

function addXP(amount) {
  xp += amount;
  localStorage.setItem('xp_div_dec', xp);
  updateXPUI();
}

function resetXP() {
  xp = 0;
  localStorage.setItem('xp_div_dec', xp);
  updateXPUI();
  alert('Marcador XP reiniciado.');
}

// CONTROL DE NAVEGACIÓN
function go(id) {
  document.querySelectorAll('.sec').forEach(s => s.classList.remove('active'));
  document.querySelectorAll('.nav-t').forEach(t => t.classList.remove('active'));
  
  const targetSec = document.getElementById(id);
  if(targetSec) targetSec.classList.add('active');
  
  const targetTab = document.querySelector(`[data-s="${id}"]`);
  if(targetTab) targetTab.classList.add('active');
  
  activeTab = id;
}

// LÓGICA: LABORATORIO INTERACTIVO
function labShowParte(parte) {
  document.querySelectorAll('.lab-btn').forEach(b => b.classList.remove('active-pri', 'active-sec'));
  const btn = document.querySelector(`[data-lab="${parte}"]`);
  if(btn) btn.classList.add('active-pri');

  const desc = document.getElementById('lab-sentence');
  const lblDivisor = document.getElementById('lab-lbl-divisor');
  const lblCociente = document.getElementById('lab-lbl-cociente');
  const lblVerif = document.getElementById('lab-lbl-verif');

  if (parte === 'dividendo') {
    desc.innerHTML = "<strong>Dividendo (4.5):</strong> Representa la cantidad inicial. Al multiplicarlo por 10 se convierte en 45 décimas.";
    document.getElementById('lab-bg-dividendo').style.opacity = "1";
  } else if (parte === 'divisor') {
    desc.innerHTML = "<strong>Divisor (0.5):</strong> Es menor que 1. Al multiplicarlo por 10 para normalizarlo se transforma en el entero 5.";
    lblDivisor.style.opacity = "1";
    document.getElementById('lab-bg-divisor').style.opacity = "0.8";
  } else if (parte === 'cociente') {
    desc.innerHTML = "<strong>Cociente (9):</strong> ¡Observa! El resultado es mayor que el dividendo original (4.5) porque el divisor original era menor que 1.";
    lblCociente.style.opacity = "1";
    lblVerif.style.opacity = "1";
    document.getElementById('lab-bg-cociente').style.opacity = "0.8";
  }
}

function checkLabChallenge() {
  addXP(5);
  alert("¡Laboratorio completado con éxito! +5 XP");
}

// LÓGICA: FLASHCARDS
function loadFC() {
  const card = flashcards[currentFCIdx];
  document.getElementById('fcW').innerText = card.w;
  document.getElementById('fcA').innerText = card.a;
  document.getElementById('fcCtr').innerText = `${currentFCIdx + 1} / ${flashcards.length}`;
  document.getElementById('fcInner').classList.remove('flipped');
}

function flipCard() {
  document.getElementById('fcInner').classList.toggle('flipped');
  if (!fcsFlipped.has(currentFCIdx)) {
    fcsFlipped.add(currentFCIdx);
    addXP(1);
  }
}

function nextFC() {
  currentFCIdx = (currentFCIdx + 1) % flashcards.length;
  loadFC();
}

function prevFC() {
  currentFCIdx = (currentFCIdx - 1 + flashcards.length) % flashcards.length;
  loadFC();
}

// LÓGICA: QUIZ
let qzIdx = 0;
let qzSelected = null;

function loadQuiz() {
  const q = quizQuestions[qzIdx];
  document.getElementById('qzProg').innerText = `Pregunta ${qzIdx + 1} de ${quizQuestions.length}`;
  document.getElementById('qzQ').innerText = q.q;
  
  const optsContainer = document.getElementById('qzOpts');
  optsContainer.innerHTML = '';
  
  q.o.forEach((opt, idx) => {
    const btn = document.createElement('button');
    btn.className = 'qz-opt';
    btn.innerText = opt;
    btn.onclick = () => selectQuizOpt(idx);
    optsContainer.appendChild(btn);
  });
  
  document.getElementById('fbQz').classList.remove('show');
}

function selectQuizOpt(idx) {
  qzSelected = idx;
  const nodes = document.getElementById('qzOpts').children;
  for(let i=0; i<nodes.length; i++) {
    nodes[i].classList.remove('sel');
  }
  nodes[idx].classList.add('sel');
}

function checkQz() {
  if (qzSelected === null) return;
  const q = quizQuestions[qzIdx];
  const fb = document.getElementById('fbQz');
  fb.classList.add('show');
  
  if (qzSelected === q.a) {
    fb.className = 'fb show ok';
    fb.innerText = '¡Correcto! Algoritmo ejecutado de forma impecable.';
    addXP(5);
    setTimeout(() => {
      qzIdx = (qzIdx + 1) % quizQuestions.length;
      qzSelected = null;
      loadQuiz();
    }, 1500);
  } else {
    fb.className = 'fb show err';
    fb.innerText = 'Respuesta incorrecta. Revisa el movimiento del punto decimal.';
  }
}

function useHintQz() {
  const q = quizQuestions[qzIdx];
  alert(`Pista: ${q.h}`);
}

function resetQz() {
  qzIdx = 0;
  qzSelected = null;
  loadQuiz();
}

// LÓGICA: CLASIFICA
function loadClassifica() {
  const bank = document.getElementById('clsBank');
  bank.innerHTML = '';
  
  classItems.forEach((item, idx) => {
    const d = document.createElement('div');
    d.className = 'wb-item';
    d.innerText = item.t;
    d.onclick = () => {
      // Arquitectura simplificada para compatibilidad móvil directa sin Drag & Drop nativo áspero
      const col = prompt("¿Clasificar en columna 1 (Mayor) o columna 2 (Menor)? Ingrese 1 o 2:");
      if (col === '1') document.getElementById('items-left').appendChild(d);
      if (col === '2') document.getElementById('items-right').appendChild(d);
    };
    bank.appendChild(d);
  });
}

function checkClass() {
  const fb = document.getElementById('fbCls');
  fb.className = 'fb show ok';
  fb.innerText = 'Estructuras analizadas. ¡Buen trabajo clasificando la influencia del divisor!';
  addXP(5);
}

function resetClass() {
  document.getElementById('items-left').innerHTML = '';
  document.getElementById('items-right').innerHTML = '';
  loadClassifica();
}

// LÓGICA: IDENTIFICA
let idIdx = 0;
function loadIdentifica() {
  const data = identStatements[idIdx];
  const container = document.getElementById('idSent');
  container.innerHTML = '';
  
  const words = data.text.split(' ');
  words.forEach(w => {
    const span = document.createElement('span');
    span.className = 'id-word';
    span.innerText = w;
    span.onclick = () => {
      document.querySelectorAll('.id-word').forEach(x => x.classList.remove('selected'));
      span.classList.add('selected');
      evalIdentifica(w, data);
    };
    container.appendChild(span);
  });
  document.getElementById('fbId').classList.remove('show');
}

function evalIdentifica(word, data) {
  const fb = document.getElementById('fbId');
  fb.classList.add('show');
  if (word.includes(data.target.replace('.', ''))) {
    fb.className = 'fb show ok';
    fb.innerText = `¡Excelente! Detectaste el error. ${data.info}`;
    addXP(5);
  } else {
    fb.className = 'fb show err';
    fb.innerText = 'Esa palabra describe un proceso correcto. Busca la anomalía.';
  }
}

function nextId() {
  idIdx = (idIdx + 1) % identStatements.length;
  loadIdentifica();
}

function resetId() {
  idIdx = 0;
  loadIdentifica();
}

// LÓGICA: COMPLETA
let cmpIdx = 0;
let cmpSel = null;

function loadCompleta() {
  const data = completePhrases[cmpIdx];
  document.getElementById('cmpProg').innerText = `Regla ${cmpIdx + 1} de ${completePhrases.length}`;
  
  const txt = data.s.replace('_______', '<span class="blank" id="cmpBlank">_______</span>');
  document.getElementById('cmpSent').innerHTML = txt;
  
  const opts = document.getElementById('cmpOpts');
  opts.innerHTML = '';
  
  data.o.forEach(o => {
    const b = document.createElement('button');
    b.className = 'cmp-opt';
    b.innerText = o;
    b.onclick = () => {
      cmpSel = o;
      document.getElementById('cmpBlank').innerText = o;
    };
    opts.appendChild(b);
  });
  document.getElementById('fbCmp').classList.remove('show');
}

function checkCmp() {
  if(!cmpSel) return;
  const data = completePhrases[cmpIdx];
  const fb = document.getElementById('fbCmp');
  fb.classList.add('show');
  
  if(cmpSel === data.a) {
    fb.className = 'fb show ok';
    fb.innerText = '¡Fórmula conceptual completada correctamente!';
    addXP(5);
    setTimeout(() => {
      cmpIdx = (cmpIdx + 1) % completePhrases.length;
      cmpSel = null;
      loadCompleta();
    }, 1200);
  } else {
    fb.className = 'fb show err';
    fb.innerText = 'La palabra elegida altera el sentido matemático real de la regla.';
  }
}

// LÓGICA: WIDGET CONSTRUCTOR
let bldrVal = 0.0;
function loadWidgetBuilder() {
  document.getElementById('bldrDisplay').innerText = bldrVal.toFixed(1);
  const slots = document.getElementById('bldrSlots');
  slots.innerHTML = '';
  
  // Controles Decenas, Unidades y Décimas
  const config = [
    { label: 'Unidades', step: 1.0 },
    { label: 'Décimas', step: 0.1 }
  ];
  
  config.forEach(c => {
    const slot = document.createElement('div');
    slot.className = 'bldr-slot';
    slot.innerHTML = `
      <span class="bldr-label">${c.label}</span>
      <button class="bldr-btn" onclick="modBldr(${c.step})">+</button>
      <button class="bldr-btn" onclick="modBldr(${-c.step})">-</button>
    `;
    slots.appendChild(slot);
  });
}

function modBldr(val) {
  bldrVal = Math.max(0, bldrVal + val);
  document.getElementById('bldrDisplay').innerText = bldrVal.toFixed(1);
}

function checkBldr() {
  const fb = document.getElementById('fbBldr');
  fb.classList.add('show');
  if (Math.abs(bldrVal - 6.0) < 0.01) {
    fb.className = 'fb show ok';
    fb.innerText = '¡Construcción matemática perfecta! 3 ÷ 0.5 es igual a 6.';
    addXP(4);
  } else {
    fb.className = 'fb show err';
    fb.innerText = 'El valor construido no concuerda con el cociente real.';
  }
}

function nextBldr() {
  bldrVal = 0.0;
  document.getElementById('bldrTarget').innerText = "1.2 ÷ 0.3 = ?";
  loadWidgetBuilder();
  // El usuario debe apuntar a 4.0
}

// LÓGICA: WIDGET COMPARADOR DE MAGNITUDES
const compData = [
  { t: '8 ÷ 0.2', rel: 'gt', txt: 'Cociente: 40 (Mayor)' },
  { t: '5 ÷ 2.5', rel: 'lt', txt: 'Cociente: 2 (Menor)' }
];
let compIdx = 0;

function loadWidgetComp() {
  const data = compData[compIdx];
  document.getElementById('cmpVisA').innerText = data.t;
  document.getElementById('cmpVisBarA').style.width = '60%';
  document.getElementById('cmpVisBarB').style.width = '20%';
  document.getElementById('cmpVisB').innerText = '= ?';
  document.getElementById('cmpVisPctB').innerText = 'Estimando...';
  document.getElementById('fbComp').classList.remove('show');
}

function ansComp(rel) {
  const data = compData[compIdx];
  const fb = document.getElementById('fbComp');
  fb.classList.add('show');
  
  if (rel === data.rel) {
    fb.className = 'fb show ok';
    fb.innerText = '¡Predicción geométrica correcta!';
    document.getElementById('cmpVisB').innerText = data.rel === 'gt' ? '40' : '2';
    document.getElementById('cmpVisBarB').style.width = data.rel === 'gt' ? '90%' : '30%';
    document.getElementById('cmpVisPctB').innerText = data.txt;
    addXP(3);
  } else {
    fb.className = 'fb show err';
    fb.innerText = 'Predicción errada. Evalúa si el divisor es fraccionario o entero mayor que 1.';
  }
}

function nextComp() {
  compIdx = (compIdx + 1) % compData.length;
  loadWidgetComp();
}

// LÓGICA: CONTRARRELOJ RETO
let retoTimerVal = 30;
let retoInterval = null;
let retoHits = 0;
let retoErrors = 0;
const retoItems = [
  { w: '4 ÷ 0.1', a: 'Cociente Mayor', b: 'Cero al cociente', ans: 'a' },
  { w: '6.03 ÷ 3', a: 'Cociente Mayor', b: 'Cero al cociente', ans: 'b' },
  { w: '9 ÷ 0.5', a: 'Cociente Mayor', b: 'Cero al cociente', ans: 'a' }
];
let retoCurrIdx = 0;

function startReto() {
  if (retoInterval) clearInterval(retoInterval);
  retoTimerVal = 30;
  retoHits = 0;
  retoErrors = 0;
  retoCurrIdx = 0;
  
  document.getElementById('retoTimer').innerText = `⏱ ${retoTimerVal}`;
  document.getElementById('retoBarFill').style.width = '100%';
  
  retoInterval = setInterval(() => {
    retoTimerVal--;
    document.getElementById('retoTimer').innerText = `⏱ ${retoTimerVal}`;
    document.getElementById('retoBarFill').style.width = `${(retoTimerVal / 30) * 100}%`;
    
    if(retoTimerVal <= 0) {
      clearInterval(retoInterval);
      document.getElementById('retoWord').innerText = '¡Tiempo agotado!';
      alert(`Reto terminado. Aciertos: ${retoHits}, Errores: ${retoErrors}`);
    }
  }, 1000);
  
  presentRetoItem();
}

function presentRetoItem() {
  const item = retoItems[retoCurrIdx];
  document.getElementById('retoWord').innerText = item.w;
  document.getElementById('retoBtn-a').innerText = item.a;
  document.getElementById('retoBtn-b').innerText = item.b;
}

function ansReto(opt) {
  if (retoTimerVal <= 0) return;
  const item = retoItems[retoCurrIdx];
  
  if(opt === item.ans) {
    retoHits++;
    addXP(1);
  } else {
    retoErrors++;
  }
  
  document.getElementById('retoScore').innerText = `✅ ${retoHits} Éxitos | ❌ ${retoErrors} Fallos`;
  retoCurrIdx = (retoCurrIdx + 1) % retoItems.length;
  presentRetoItem();
}

function resetReto() {
  clearInterval(retoInterval);
  document.getElementById('retoTimer').innerText = '⏱ 30';
  document.getElementById('retoBarFill').style.width = '100%';
  document.getElementById('retoWord').innerText = '¡Listo para el Impacto!';
  document.getElementById('retoScore').innerText = `✅ 0 Éxitos | ❌ 0 Fallos`;
}

// LÓGICA: SOPA DE LETRAS
function loadSopa() {
  const wordsCont = document.getElementById('sopaWords');
  wordsCont.innerHTML = '';
  sopaPalabras.forEach(w => {
    const s = document.createElement('span');
    s.className = 'sopa-w';
    s.id = `sw-${w}`;
    s.innerText = w;
    wordsCont.appendChild(s);
  });
  
  const gridCont = document.getElementById('sopaGrid');
  gridCont.innerHTML = '';
  gridCont.style.gridTemplateColumns = `repeat(${sopaGridData[0].length}, 32px)`;
  
  sopaGridData.forEach((row, rIdx) => {
    row.forEach((char, cIdx) => {
      const cell = document.createElement('div');
      cell.className = 'sopa-cell';
      cell.innerText = char;
      cell.onclick = () => selectSopaCell(cell, char);
      gridCont.appendChild(cell);
    });
  });
}

let activeSopaWord = "";
function selectSopaCell(cell, char) {
  cell.classList.toggle('sopa-sel');
  activeSopaWord += char;
  
  // Validar si la palabra acumulada coincide con alguna de la sopa
  sopaPalabras.forEach(p => {
    if(activeSopaWord.includes(p)) {
      const targetWord = document.getElementById(`sw-${p}`);
      if(targetWord && !targetWord.classList.contains('found')) {
        targetWord.classList.add('found');
        addXP(5);
        activeSopaWord = "";
        alert(`¡Palabra encontrada: ${p}! +5 XP`);
      }
    }
  });
}

// LÓGICA: GENERADOR DE TAREAS
function genTask() {
  const type = document.getElementById('tgType').value;
  const count = parseInt(document.getElementById('tgCount').value);
  const out = document.getElementById('tgOut');
  out.innerHTML = '';
  
  for(let i = 1; i <= count; i++) {
    const item = document.createElement('div');
    item.className = 'tg-task';
    if(type === 'explain') {
      item.innerHTML = `
        <div class="tg-task-num">${i}.</div>
        <div class="tg-task-content">Explica el proceso paso a paso para resolver la división: <strong>${(i*1.2).toFixed(1)} ÷ 0.3</strong>.
          <div class="tg-answer">Respuesta sugerida: Multiplicar por 10 para transformar a ${(i*12)} ÷ 3. El cociente es ${(i*4)}.</div>
        </div>
      `;
    } else {
      item.innerHTML = `
        <div class="tg-task-num">${i}.</div>
        <div class="tg-task-content">Clasifica el impacto en el tamaño del dividendo para: <strong>${(i*2)} ÷ 0.05</strong>.
          <div class="tg-answer">Respuesta sugerida: Al ser el divisor menor que 1, el cociente se expande notablemente.</div>
        </div>
      `;
    }
    out.appendChild(item);
  }
}

function toggleAns() {
  document.querySelectorAll('.tg-answer').forEach(ans => {
    ans.style.display = ans.style.display === 'block' ? 'none' : 'block';
  });
}

// LÓGICA: EVALUACIÓN FINAL
function genEval() {
  const out = document.getElementById('evalOut');
  out.innerHTML = `
    <div class="eval-section-title">Parte I: Selección Múltiple <span class="eval-pts">(50 Puntos)</span></div>
    <div class="eval-item">
      <div class="eval-q"><span class="eval-num">1.</span> <span class="eval-q-text">¿Qué sucede al dividir 9.5 entre un divisor decimal como 0.5?</span></div>
      <div class="eval-mc-opts">
        <label class="eval-mc-opt"><input type="radio" name="ev1"> A) El cociente es menor a 9.5</label>
        <label class="eval-mc-opt"><input type="radio" name="ev1"> B) El cociente es mayor a 9.5</label>
      </div>
      <div class="eval-answer">Clave: B. Divisores menores a la unidad provocan una ampliación del dividendo en el cociente.</div>
    </div>
    <div class="eval-item">
      <div class="eval-q"><span class="eval-num">2.</span> <span class="eval-q-text">Calcule el cociente de la operación exacta: 1.05 ÷ 5</span></div>
      <div class="eval-mc-opts">
        <label class="eval-mc-opt"><input type="radio" name="ev2"> A) 0.21</label>
        <label class="eval-mc-opt"><input type="radio" name="ev2"> B) 0.021</label>
        <label class="eval-mc-opt"><input type="radio" name="ev2"> C) 0.201</label>
      </div>
      <div class="eval-answer">Clave: A. 1 no alcanza a 5, genera cero al cociente en las décimas (0.21).</div>
    </div>
  `;
}

function toggleEvalAns() {
  document.querySelectorAll('.eval-answer').forEach(ans => {
    ans.style.display = ans.style.display === 'block' ? 'none' : 'block';
  });
}

function printEval() {
  window.print();
}

// CONFIGURACIONES DE ENTORNO Y ACCESIBILIDAD
function toggleTheme() {
  const curr = document.documentElement.getAttribute('data-theme');
  document.documentElement.setAttribute('data-theme', curr === 'dark' ? 'light' : 'dark');
}

function toggleLetra() {
  document.body.classList.toggle('letra-grande');
}

// CONTROL DE DIPLOMA Y CAPTURA
function openDiploma() {
  document.getElementById('diplomaDate').innerText = new Date().toLocaleDateString();
  document.getElementById('diplomaOverlay').classList.add('open');
}

function closeDiploma() {
  document.getElementById('diplomaOverlay').classList.remove('open');
}

function updateDiplomaName(val) {
  document.getElementById('diplName').innerText = val || "Estudiante";
}

function captureDiploma() {
  const target = document.querySelector('.diploma-card');
  if (typeof html2canvas !== 'undefined') {
    html2canvas(target).then(canvas => {
      const link = document.createElement('a');
      link.download = 'Evidencia-Division-Decimales.png';
      link.href = canvas.toDataURL();
      link.click();
    });
  } else {
    alert("Función de guardado fotográfico lista. (Asegúrate de que html2canvas esté correctamente cargado).");
  }
}

function compartirMision() {
  const msg = encodeURIComponent("¡Hola! Estoy logrando dominar la Misión de División de Decimales en policastsapien.com 🚀");
  window.open(`https://api.whatsapp.com/send?text=${msg}`, '_blank');
}